287	    /// Where a member went, for the tables.
288	    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
289	    enum Placed {
290	        Row,
291	        Used,
292	        Collapsed,
293	        AsToday,
294	    }
295	
296	    fn inherited(name: &str) -> Member {
297	        Member { name: name.to_owned(), ..Member::default() }
298	    }
299	
300	    fn ambient(name: &str) -> Member {
301	        Member { ambient: true, ..inherited(name) }
302	    }
303	
304	    fn strings(names: &[&str]) -> Vec<String> {
305	        names.iter().map(|name| (*name).to_owned()).collect()
306	    }
307	
308	    fn reading(names: &[&str]) -> Body {
309	        Body { reads: strings(names), ..Body::default() }
310	    }
311	
312	    fn named(name: &str, prop: Option<&str>) -> Attribute {
313	        Attribute::Named { name: name.to_owned(), prop: prop.map(str::to_owned) }
314	    }
315	
316	    fn element(target: Target, attributes: Vec<Attribute>) -> Element {
317	        Element { target, attributes }
318	    }
319	
320	    fn with(members: Vec<Member>, body: Option<Body>) -> Evidence {
321	        Evidence { members, body, ..Evidence::default() }
322	    }
323	
324	    fn placed(shown: &Shown, name: &str) -> Option<Placed> {
325	        let lists = [
326	            (&shown.rows, Placed::Row),
327	            (&shown.used, Placed::Used),
328	            (&shown.collapsed, Placed::Collapsed),
329	            (&shown.as_today, Placed::AsToday),
330	        ];
331	        lists.into_iter().find(|(list, _)| list.iter().any(|n| n == name)).map(|(_, placed)| placed)
332	    }
333	
334	    /// One case of a table: its label, its evidence, and where each named member must go.
335	    type Case<'a> = (&'a str, Evidence, &'a [(&'a str, Placed)]);
336	
337	    /// Runs each case and checks where every named member went.
338	    fn table(cases: Vec<Case<'_>>) {
339	        for (case, evidence, expected) in cases {
340	            let shown = decide(&evidence);
341	            for (name, want) in expected {
342	                assert_eq!(placed(&shown, name), Some(*want), "{case}: {name}");
343	            }
344	        }
345	    }
