371	impl Revision {
372	    /// This revision's parsed state with `changed` re-read: re-parsed, created or deleted. With `extend_dependencies`,
373	    /// names the file newly references are loaded now; a lazy revision loads them when a component needs them.
374	    fn apply_change<'c>(
375	        &self,
376	        options: &PipelineOptions,
377	        changed: &'c Utf8Path,
378	        extend_dependencies: bool,
379	    ) -> Applied<'c> {
380	        let mut global = (*self.global).clone();
381	        let mut named_types = (*self.named_types).clone();
382	        let mut file_diagnostics = self.file_diagnostics.clone();
383	        let mut files = (*self.files).clone();
384	        let mut dependencies = self.dependencies.clone();
385	        let mut demands = Vec::new();
386	        let mut bare_names: FxHashSet<String> = bare_names_declared(changed, &self.global.enums).into_iter().collect();
387	        bare_names.extend(bare_names_declared(changed, &self.global.const_arrays));
388	        let mut react_namespace = named_types.declares_react_namespace(changed);
389	        global.remove_file(changed);
390	        named_types.remove_file(changed);
391	        file_diagnostics.remove(changed);
392	
393	        let read = match std::fs::read_to_string(changed) {
394	            Ok(source) => Some((source, None)),
395	            // Deleted: its declarations and diagnostics leave with it.
396	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
397	            // Unreadable (permissions, invalid UTF-8): declares nothing, exactly as in a cold run.
398	            Err(e) => Some((String::new(), Some(Diagnostic::io_read_error(changed, &e)))),
399	        };
400	        let created = match read {
401	            None => {
402	                files.remove(changed);
403	                false
404	            }
405	            Some((source, io_diag)) => {
406	                let mut data = crate::extractor::parse_file(changed, &source);
407	                let mut diags: Vec<Diagnostic> = io_diag.into_iter().collect();
408	                diags.append(&mut data.diagnostics);
409	                if !diags.is_empty() {
410	                    file_diagnostics.insert(changed.to_owned(), diags);
411	                }
412	                bare_names.extend(bare_names_declared(changed, &data.enums));
413	                bare_names.extend(bare_names_declared(changed, &data.const_arrays));
414	                if options.load_dependencies {
415	                    demands = dependency_types::project_demands(changed, &data);
416	                }
417	                // Only names no earlier revision loaded cost a load; the new layer keeps everything the old one had.
418	                if let (true, Some(layer)) = (extend_dependencies, &self.dependencies) {
419	                    let missing = layer.missing(&demands);
420	                    if !missing.is_empty() {
421	                        let extended = dependency_types::load(missing, options, Some(layer));
422	                        named_types.fallback = Some(extended.named_types.clone());
423	                        dependencies = Some(Arc::new(extended));
424	                    }
425	                }
426	                named_types.merge_file(&data);
427	                react_namespace |= named_types.declares_react_namespace(changed);
428	                global.merge(changed, data);
429	                files.insert(changed.to_owned())
430	            }
431	        };
432	        Applied {
433	            global,
434	            named_types,
435	            file_diagnostics,
436	            files,
437	            dependencies,
438	            change: Change { file: changed, created, bare_names, react_namespace },
439	            demands,
440	        }
441	    }
442	}
