1	//! The evidence a component's props type gives about each member it reaches (ADR 0028, slice T2): the props type's
2	//! own members, the keys a `Pick` names, the members that redeclare or narrow a base member, the required and defaulted
3	//! ones, and the JSDoc and literal-union flags [`decide`](super::decide) only orders rows by.
4	//!
5	//! [`members`] is the one function that builds it, from the same inputs in both lanes: what the props type writes
6	//! ([`PropsType`], read from its syntax, so the same for both), and the lane's answer (its listed props and its
7	//! collapsed layers). The checker lane's props carry the checker's `parent` and `declarations` (ADR 0026 S7a), the
8	//! structural lane's the resolver's; where neither names a base, a collapsed layer that holds the member does. A member
9	//! only a layer names is known by its name alone in both lanes, so it is never required or documented here.
10	
11	use std::collections::BTreeSet;
12	
13	use super::Member;
14	use crate::types::collected::{CollectedInterface, CollectedType, CollectedTypeAlias, ComponentMapping, ExtendsRef};
15	use crate::types::output::{InheritedLayer, ParsedProp, PropParent, PropType};
16	
17	/// How deep [`PropsType::read`] follows aliases of `Pick` keys, so a cyclic alias ends.
18	const MAX_ALIAS_DEPTH: u8 = 8;
19	
20	/// A declaration the props type names, as the caller finds it by name from the component's file.
21	#[derive(Debug, Clone, Copy)]
22	pub(crate) enum Declaration<'a> {
23	    /// An interface.
24	    Interface(&'a CollectedInterface),
25	    /// A type alias.
26	    Alias(&'a CollectedTypeAlias),
27	}
28	
29	/// What a component's props type says itself, read once from its syntax.
30	#[derive(Debug, Clone, Default, PartialEq, Eq)]
31	pub(crate) struct PropsType {
32	    /// The interface the props type is, when it is one: a member whose `parent` it is was declared here.
33	    interface: Option<(String, String)>,
34	    /// The members the props type writes itself: its interface's own members and the fields of its type literals.
35	    own: BTreeSet<String>,
36	    /// The keys a `Pick` in the props type itself names. An `Omit` names nothing kept.
37	    picked: BTreeSet<String>,
38	    /// The props the signature gives a default: a destructuring default or `defaultProps`.
39	    defaulted: BTreeSet<String>,
40	}
41	
42	impl PropsType {
43	    /// The members the props type writes itself, as a lane hands a forwarding target's props to `forwarding`: own and
44	    /// not ambient, in name order. Read from the syntax, so the same in both lanes.
45	    pub(crate) fn own_members(&self) -> Vec<Member> {
46	        self.own.iter().map(|name| Member { name: name.clone(), own: true, ..Member::default() }).collect()
47	    }
48	
49	    /// Reads the props type of `mapping`, finding each name it writes with `lookup`. A base it extends or intersects
50	    /// is not entered: its members are inherited, and the lanes report them.
51	    pub(crate) fn read<'a>(mapping: &ComponentMapping, lookup: impl Fn(&str) -> Option<Declaration<'a>>) -> Self {
52	        let mut read = Self { defaulted: mapping.param_defaults.keys().cloned().collect(), ..Self::default() };
53	        // `props: Pick<Base, Keys>` is the mapping's own name and arguments, not a declaration to look up.
54	        read.pick(&mapping.props_type_name, &mapping.props_type_args, &lookup);
55	        match lookup(&mapping.props_type_name) {
56	            Some(Declaration::Interface(interface)) => {
57	                read.interface = Some((interface.name.to_string(), interface.file_path.to_string()));
58	                read.own.extend(interface.props.iter().map(|prop| prop.name.clone()));
59	                for base in &interface.extends {
60	                    if let ExtendsRef::SameFile { name, type_args }
61	                    | ExtendsRef::Imported { local_name: name, type_args, .. } = base
62	                    {
63	                        read.pick(name, type_args, &lookup);
64	                    }
65	                }
66	            }
67	            Some(Declaration::Alias(alias)) => match alias {
68	                CollectedTypeAlias::Pick { keys, .. } => read.keys(keys, &lookup, 0),
69	                // A union's arms are each the props type (a discriminated union's fields are its own).
70	                CollectedTypeAlias::Intersection { members, .. } | CollectedTypeAlias::Union { members, .. } => {
71	                    members.iter().for_each(|member| read.part(member, &lookup));
72	                }
73	                CollectedTypeAlias::Passthrough { target: part, .. }
74	                | CollectedTypeAlias::Partial { base: part, .. }
75	                | CollectedTypeAlias::Required { base: part, .. } => read.part(part, &lookup),
76	                CollectedTypeAlias::Omit { .. } | CollectedTypeAlias::LiteralUnion { .. } => {}
77	            },
78	            None => {}
79	        }
80	        read
81	    }
82	
83	    /// One part of the props type: a type literal's fields are its own, an intersection's parts are parts, a `Pick`
84	    /// names its keys; any other name is a base.
85	    fn part<'a>(&mut self, part: &CollectedType, lookup: &impl Fn(&str) -> Option<Declaration<'a>>) {
86	        match part {
87	            CollectedType::Object(fields) | CollectedType::Callable { fields, .. } => {
88	                self.own.extend(fields.iter().map(|field| field.name.clone()));
89	            }
90	            CollectedType::Intersection(parts) | CollectedType::Union(parts) => {
91	                parts.iter().for_each(|part| self.part(part, lookup));
92	            }
93	            CollectedType::Named { name, args } => self.pick(name, args, lookup),
94	            _ => {}
95	        }
96	    }
97	
98	    /// The keys of `name<args>` when it is `Pick<Base, Keys>`.
99	    fn pick<'a>(&mut self, name: &str, args: &[CollectedType], lookup: &impl Fn(&str) -> Option<Declaration<'a>>) {
100	        if let ("Pick", [_, keys]) = (name, args) {
101	            self.keys(keys, lookup, 0);
102	        }
103	    }
104	
105	    /// The string literal keys `keys` names, through unions and aliases.
106	    fn keys<'a>(&mut self, keys: &CollectedType, lookup: &impl Fn(&str) -> Option<Declaration<'a>>, depth: u8) {
107	        match keys {
108	            CollectedType::StringLiteral(key) => {
109	                self.picked.insert(key.to_string());
110	            }
111	            CollectedType::Union(keys) => keys.iter().for_each(|key| self.keys(key, lookup, depth)),
112	            CollectedType::Named { name, args } if args.is_empty() && depth < MAX_ALIAS_DEPTH => match lookup(name) {
113	                Some(Declaration::Alias(CollectedTypeAlias::LiteralUnion { members, .. })) => {
114	                    self.picked.extend(members.iter().cloned());
115	                }
116	                Some(Declaration::Alias(CollectedTypeAlias::Passthrough { target, .. })) => {
117	                    self.keys(target, lookup, depth + 1);
118	                }
119	                Some(Declaration::Alias(CollectedTypeAlias::Union { members, .. })) => {
120	                    members.iter().for_each(|key| self.keys(key, lookup, depth + 1));
121	                }
122	                _ => {}
123	            },
124	            _ => {}
125	        }
126	    }
127	
128	    /// Whether `parent` is the interface the props type is.
129	    fn declares(&self, parent: &PropParent) -> bool {
